// Registers the recompiled code sections with the runtime.
//
// Adapted from src/main/register_overlays.cpp of the WWF WrestleMania 2000 recomp
// (GPL-3.0): https://github.com/jessetbh/WWFWrestleMania2000Recomp
//
// recomp_overlays.inl is generated by N64Recomp (python3 tools/regen.py). It holds
// the section table: boot code plus the three inflated code streams.
#include "kigold_decls.h"
#include "../../RecompiledFuncs/recomp_overlays.inl"

#include "librecomp/overlays.hpp"

void kigold::register_overlays() {
    recomp::overlays::overlay_section_table_data_t sections {
        .code_sections = section_table,
        .num_code_sections = ARRLEN(section_table),
        .total_num_sections = num_sections,
    };

    recomp::overlays::overlays_by_index_t overlays {
        .table = overlay_sections_by_index,
        .len = ARRLEN(overlay_sections_by_index),
    };

    recomp::overlays::register_overlays(sections, overlays);
}
